#!/usr/bin/env python3
"""Build a local-only 2023 May source-restoration proposal package from frozen evidence."""
import csv,hashlib,json,math
from datetime import datetime,timezone
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PKG=ROOT/'proposals/restored_source_only_2023_may_outtemp'
PKG.mkdir(parents=True,exist_ok=True)
source=[r for r in json.loads((ROOT/'data/b5_2022_2023_eu_old_gap_source_rows.json').read_text())['rows'] if 1685274900<r['dateTime']<1685332200]
context=json.loads((ROOT/'data/b5_2022_2023_luhamet_context.json').read_text())['rows']
ref={int(r['observed_at_utc']):r for r in context}
boundary=json.loads((ROOT/'data/b5_2022_2023_reconstruction_boundary_context.json').read_text())['rows']
byts={int(r['dateTime']):r for r in boundary}
left=byts[1685274900];right=byts[1685332200]
state=json.loads((ROOT/'data/b5_2023_may_gap_source_first_current_state.json').read_text())['result'][0]
baseline=json.loads((ROOT/'data/b5_2023_may_gap_widened_luhamet_baseline.json').read_text())['rows']
base={r['segment']:r for r in baseline}
assert len(source)==190 and len(ref)>=190 and state['eu_old_unique_timestamps']==190
presence={'loucka_reconstruction':False,'pocasi-loucka.eu':False,'pocasi-loucka.eu_GW1000':False,'pocasi-loucka.eu_old':True,'old_weewx':False,'weewx_WH1080':False}
reason=('RESTORED; MODERATE provenance: exact 5-minute outTemp row from owner-attested historical archive pocasi-loucka.eu_old. Exact archive origin/export and intent of historical omission are unknown; previous cleaning cannot be excluded. All 190 timestamps are present only in this archive and absent from the other five checked archives and reconstruction_changes. Unit/interval, exact timestamp, continuous source sequence, physical range and step changes, current target absence, exact LuhaMet context, and local 30-day pre/post reference baselines were checked. This restores a historical source measurement, not a statistical estimate; regional agreement supports plausibility but is not local truth. outTemp only; other variables remain NULL.')
ops=[];metas=[];targets=[];errors=[];steps=[]
for i,r in enumerate(sorted(source,key=lambda x:x['dateTime'])):
 ts=int(r['dateTime']);temp=float(r['outTemp']);refrow=ref[ts];rt=float(refrow['temperature_c'])
 interp=float(left['outTemp'])+(float(right['outTemp'])-float(left['outTemp']))*(ts-1685274900)/(1685332200-1685274900)
 delta=temp-rt;idelta=temp-interp;errors.append(delta)
 if i:steps.append(temp-float(sorted(source,key=lambda x:x['dateTime'])[i-1]['outTemp']))
 op={'operation':'insert','timestamp':ts,'variable':'outTemp','new_value':temp,'expected_old_value':None,'source_database':'pocasi-loucka.eu_old','source_time':ts,'source_value':temp,'reason':reason,'us_units':16,'interval_minutes':5}
 ops.append(op)
 source_values={k:r.get(k) for k in ('outTemp','outHumidity','rain','rainRate','windSpeed','windGust','windDir','barometer','pressure','altimeter')}
 meta={'timestamp':ts,'utc':datetime.fromtimestamp(ts,timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ'),'classification':'RESTORED','operation':'insert outTemp only','confidence':'MODERATE','source_lineage':'OWNER_ATTESTED archive role; exact database origin/export lineage unknown. Archive is a historical source in the owner-described merge ecosystem; earlier cleaning/intentional omission remains possible.',
  'uncertainty':'This is a source measurement restoration, not a model estimate; no individual predictive interval applies. LuhaMet is regional plausibility context only. Provenance confidence MODERATE.',
  'source_evidence':{'archive':'pocasi-loucka.eu_old','source_usUnits':int(r['usUnits']),'source_interval_minutes':int(r['interval']),'source_values':source_values,'target_row_exists_in_reconstruction':False,'target_change_events_all_variables':0,'archive_row_presence_by_database':presence,
   'exact_luhamet':{'station_id':'luhamet_sehradice','temperature_c':rt,'relative_humidity_pct':refrow.get('relative_humidity_pct'),'source_minus_reference_C':delta},
   'boundary_interpolation':{'left_timestamp':1685274900,'left_outTemp_C':left['outTemp'],'right_timestamp':1685332200,'right_outTemp_C':right['outTemp'],'linear_context_C':interp,'source_minus_interpolation_C':idelta},
   'quality_checks':{'five_minute_grid':ts%300==0,'source_interval_is_5':int(r['interval'])==5,'source_units_metric_16':int(r['usUnits'])==16,'outTemp_nonnull':True,'outTemp_is_zero':temp==0,'target_absent_all_archives':True,'change_event_count':0,'exact_luhamet_pair':True,'physical_temperature_range_C':[-50,60],'source_step_from_previous_C':None if i==0 else steps[-1]},
   'source_only_other_fields':{k:source_values[k] for k in source_values if k!='outTemp'},'row_completeness':'new archive row would contain required dateTime/usUnits/interval plus outTemp; all other fields remain NULL unless separately approved.'}}
 metas.append(meta)
 targets.append({'timestamp':ts,'utc':meta['utc'],'archive_row_presence':presence,'source_outTemp':temp,'usUnits':16,'interval':5,'change_events':0})
assert len(steps)==189
summary={'operation_count':len(ops),'unique_timestamps':len({o['timestamp'] for o in ops}),'source_rows':len(source),'source_first_timestamp':source[0]['dateTime'],'source_last_timestamp':source[-1]['dateTime'],'cadence_seconds':sorted({int(b['dateTime'])-int(a['dateTime']) for a,b in zip(sorted(source,key=lambda x:x['dateTime']),sorted(source,key=lambda x:x['dateTime'])[1:])}),
 'source_temp_min_C':min(float(r['outTemp']) for r in source),'source_temp_max_C':max(float(r['outTemp']) for r in source),'max_abs_five_minute_change_C':max(map(abs,steps)),
 'LuhaMet_exact_pairs':len(errors),'source_minus_LuhaMet_bias_C':sum(errors)/len(errors),'source_minus_LuhaMet_MAE_C':sum(map(abs,errors))/len(errors),'source_minus_LuhaMet_max_abs_C':max(map(abs,errors)),
 'source_minus_endpoint_interpolation_bias_C':sum(float(m['source_evidence']['boundary_interpolation']['source_minus_interpolation_C']) for m in metas)/len(metas),'source_minus_endpoint_interpolation_MAE_C':sum(abs(float(m['source_evidence']['boundary_interpolation']['source_minus_interpolation_C'])) for m in metas)/len(metas),
 'local_30d_before':base['LOCAL_REFERENCE_30D_BEFORE'],'local_30d_after':base['LOCAL_REFERENCE_30D_AFTER'],'current_target_and_archive_presence':state,
 'all_rows_change_events':sum(int(r['change_event_count']) for r in source),'database_writes':0,'staging':False,'approval':'NOT_APPROVED','actual_mcp_dry_run':'NOT_RUN','application':'NOT_APPLIED'}
batches=[]
for start in range(0,len(ops),50):
 n=start//50+1
 batches.append({'batch_id':f'restored-2023-may-outtemp-{n:02d}-v1','size':len(ops[start:start+50]),'operations':ops[start:start+50]})
package_batches={'contract':'Weather MCP proposal format; not submitted','max_batch_size':50,'batch_count':len(batches),'batches':batches,'user_approval':'NOT_APPROVED','actual_mcp_dry_run':'NOT_RUN','application':'NOT_APPLIED'}
files={
'corrections.json':ops,'candidate_metadata.json':metas,'source_snapshot.json':source,'regional_reference_snapshot.json':[ref[int(r['dateTime'])] for r in sorted(source,key=lambda x:x['dateTime'])],
'boundary_snapshot.json':{'left':left,'right':right,'interpolation_method':'linear, descriptive comparison only'},'source_first_state.json':state,'neighbor_reference_baseline.json':baseline,
'per_target_archive_presence.json':{'archive_order':['loucka_reconstruction','pocasi-loucka.eu','pocasi-loucka.eu_GW1000','pocasi-loucka.eu_old','old_weewx','weewx_WH1080'],'targets':targets,'source_first_aggregate':state},
'weather_mcp_batches.json':package_batches,'dependency_metadata.json':{'dependency_order':'Independent one-field inserts; no dependent variable updates. Recheck current row and history before any separately approved application.','batch_limit':50,'batch_count':len(batches),'batch_sizes':[b['size'] for b in batches],'episode_split_due_to_batch_limit':True,'episode_count':1,'recheck_target_state_before_any_future_approved_application':True,'never_synthesize_other_variables':True},
'offline_simulation.json':{'simulation':'local in-memory proposal accounting only','operations':190,'physical_insert_rows':190,'updates':0,'other_variables_synthesized':0,'database_access':'NONE','database_writes':0,'staging':False,'application':'NOT_APPLIED'},
'lineage_decision.json':{'classification':'RESTORED','confidence':'MODERATE','decision':'Propose source measurement restoration for outTemp only at all 190 timestamps in the 2023-05-28/29 gap.','basis':['190 exact 5-minute values in pocasi-loucka.eu_old only','all six archive exact-key presence and reconstruction history checked read-only','all 190 target rows absent from all six archives and all change events zero','all 190 exact-time LuhaMet temperature observations','source-versus-reference errors are consistent with adjacent 30-day local-minus-LuhaMet baseline','temperature curve continuously spans both local endpoints; no zero/sentinel/large step flagged'],'limitations':['pocasi-loucka.eu_old exact origin and sensor export lineage unknown','owner confirms historical databases may have been merged, transformed, or cleaned before audit history','absence from five other archives does not prove deletion intent','LuhaMet is regional and not local truth','outHumidity, rain, rainRate, wind, pressure, and derived fields excluded; rainRate=0 is not transferred'],'not_an_estimate':True,'approval':'NOT_APPROVED','actual_mcp_dry_run':'NOT_RUN','application':'NOT_APPLIED'},
'simulation.json':{'simulation':'local in-memory proposal accounting only','operations':190,'physical_insert_rows':190,'updates':0,'other_variables_synthesized':0,'database_access':'NONE','database_writes':0,'staging':False,'application':'NOT_APPLIED'} }
for name,obj in files.items(): (PKG/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
# CSVs
with (PKG/'corrections.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(ops[0]));w.writeheader();w.writerows(ops)
with (PKG/'excluded_cases.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['scope','timestamp_or_period','field','status','reason']);w.writeheader()
 w.writerow({'scope':'2023-05-28/29 source episode','timestamp_or_period':'1685274900 < t < 1685332200','field':'outHumidity,rain,rainRate,windSpeed,windGust,windDir,barometer,pressure,altimeter,derived fields','status':'EXCLUDED_FROM_PROPOSAL','reason':'No source-first/provenance validation for these variables; rainRate=0 in source is not proof and is not transferred.'})
 w.writerow({'scope':'2023 gap event 2','timestamp_or_period':'2023-10-11T09:55:00Z/11:50:00Z','field':'all','status':'MISSING_REVIEW_REQUIRED','reason':'No exact source rows in any of six archives; no estimate proposed.'})
 w.writerow({'scope':'2023 gap event 3','timestamp_or_period':'2023-11-09T06:15:00Z/20:20:00Z','field':'all','status':'MISSING_REVIEW_REQUIRED','reason':'No exact source rows in any of six archives; no estimate proposed.'})
(PKG/'README.md').write_text(f'''# 2023 May source-only outTemp RESTORED pilot\n\n**RESTORED / MODERATE; 190 outTemp insert proposals; NOT_APPROVED / NOT_RUN / NOT_APPLIED.**\n\nThe source episode is 2023-05-28 12:00 UTC through 2023-05-29 03:45 UTC. All 190 records are exact 5-minute timestamps (`usUnits=16`, `interval=5`) in `pocasi-loucka.eu_old`; the other five checked archives have zero rows at these timestamps. No reconstruction change events were found. Values span {summary['source_temp_min_C']:.2f}–{summary['source_temp_max_C']:.2f} °C and the largest absolute 5-minute step is {summary['max_abs_five_minute_change_C']:.3f} °C.\n\nAll 190 source temperatures have exact-time LuhaMet context (bias +{summary['source_minus_LuhaMet_bias_C']:.3f} °C, MAE {summary['source_minus_LuhaMet_MAE_C']:.3f} °C, maximum absolute difference {summary['source_minus_LuhaMet_max_abs_C']:.3f} °C). Adjacent 30-day local-target/LuhaMet baselines show bias {base['LOCAL_REFERENCE_30D_BEFORE']['station_minus_reference_bias_c']:.3f} °C / MAE {base['LOCAL_REFERENCE_30D_BEFORE']['station_reference_mae_c']:.3f} °C before and bias {base['LOCAL_REFERENCE_30D_AFTER']['station_minus_reference_bias_c']:.3f} °C / MAE {base['LOCAL_REFERENCE_30D_AFTER']['station_reference_mae_c']:.3f} °C after. These comparisons support plausibility, not local truth. Source temperature follows a coherent cool-down curve and joins local endpoints; endpoint linear interpolation is not used as the proposed value.\n\nThe owner attests the archive is in the known historical merge ecosystem, but its exact origin/export and past cleaning intent remain unknown. Provenance is MODERATE. This is restoration of archived measurement values, not statistical estimation. Only outTemp is proposed; rainRate=0 and other fields are not transferred. The two other 2023 gaps without source rows remain unfilled.\n\nThe 190 operations are split into four batches of 50/50/50/40 due to the 50-operation limit. Each would insert a row with required dateTime/usUnits/interval and outTemp; all other variables remain NULL. Local validators and simulation use packaged data only.\n\nReproduce: `python3 validate.py`; `python3 simulate.py`. SQL files and all snapshots are in this package. No database write, staging, actual MCP dry-run, application, or publication has occurred.\n''')
(PKG/'PRE_APPLICATION_CHECKLIST.md').write_text('''# Pre-application checklist — 2023 May outTemp pilot\n\nProposal only; currently NOT_APPROVED / NOT_RUN / NOT_APPLIED. Do not submit or apply as part of this audit.\n\n- 190 exact source operations: see `corrections.json` and `corrections.csv`; each expects no target row and inserts only outTemp.\n- Source: `pocasi-loucka.eu_old`, exact timestamps, `usUnits=16`, `interval=5`; source and target snapshots are packaged. Provenance is MODERATE; exact origin and historical deletion intent remain unknown.\n- Regional and temporal support: exact-time LuhaMet plus 30-day local/reference summaries; these support plausibility only.\n- Recheck current state before any separately approved application: no row in all six archives and no `outTemp` or any-variable change history; abort on any changed target/source state.\n- Backup procedure: before any separately approved write, make a verified restorable backup of the target archive and relevant audit tables, record row counts and checksums for this period, and confirm the backup restore procedure.\n- If later approved: run the actual Weather MCP dry-run only after approval; inspect all 190 insert statements and all four batches; do not stage. Confirm no overlapping package/active concurrent correction and keep batch size <=50.\n- Apply only with separate explicit approval; audit reason must retain `RESTORED`, `MODERATE` provenance, source archive, timestamp/unit evidence, and limitations.\n- Rollback: use the approved batch/audit ID to reverse only the exact inserted rows, after checking no later field updates depend on them; verify both archive and audit-history states.\n- Post-check: verify exact 190 values and timestamps, units/interval, no unexpected variables (especially no synthetic rain/rainRate/RH), no duplicate keys, and audit reason/uncertainty persisted.\n''')
# Package SQL copies and local reproduction scripts.
for src,name in [(ROOT/'sql/readonly/b5_2023_may_gap_source_first_current_state.sql','source_first_current_state.sql'),(ROOT/'sql/readonly/b5_2023_may_gap_widened_luhamet_baseline.sql','widened_luhamet_baseline.sql')]:
 (PKG/name).write_text(src.read_text())
(PKG/'make_manifest.py').write_text('''#!/usr/bin/env python3\nimport hashlib,json\nfrom pathlib import Path\nr=Path(__file__).resolve().parent\nfiles=[]\nfor p in sorted(r.iterdir()):\n if p.is_file() and p.name!='manifest.json':\n  b=p.read_bytes();files.append({'path':p.name,'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()})\n(r/'manifest.json').write_text(json.dumps({'schema':'meteo-proposal-package-manifest-v1','package_id':'restored-source-only-2023-may-outtemp-v1','operation_count':190,'database_writes':0,'files':files},ensure_ascii=False,indent=2)+'\\n')\nprint('manifest entries',len(files))\n''')
(PKG/'simulate.py').write_text('''#!/usr/bin/env python3\nimport argparse,json\nfrom pathlib import Path\np=Path(__file__).resolve().parent\nops=json.loads((p/'corrections.json').read_text())\ns={'simulation':'local in-memory proposal accounting only','operations':len(ops),'physical_insert_rows':sum(x['operation']=='insert' for x in ops),'updates':sum(x['operation']=='update' for x in ops),'other_variables_synthesized':0,'batches':4,'max_batch_size':50,'database_access':'NONE','database_writes':0,'staging':False,'application':'NOT_APPLIED'}\nap=argparse.ArgumentParser();ap.add_argument('--output');a=ap.parse_args()\nif a.output:Path(a.output).write_text(json.dumps(s,indent=2)+'\\n')\nprint(json.dumps(s,indent=2))\n''')
(PKG/'validate.py').write_text('''#!/usr/bin/env python3\nimport csv,hashlib,json,math\nfrom pathlib import Path\np=Path(__file__).resolve().parent\nops=json.loads((p/'corrections.json').read_text());meta=json.loads((p/'candidate_metadata.json').read_text());src=json.loads((p/'source_snapshot.json').read_text());refs=json.loads((p/'regional_reference_snapshot.json').read_text());presence=json.loads((p/'per_target_archive_presence.json').read_text());state=json.loads((p/'source_first_state.json').read_text());base=json.loads((p/'neighbor_reference_baseline.json').read_text());batches=json.loads((p/'weather_mcp_batches.json').read_text());manifest=json.loads((p/'manifest.json').read_text())\nassert len(ops)==len(meta)==len(src)==len(refs)==190 and len({o['timestamp'] for o in ops})==190\nassert all(o['operation']=='insert' and o['variable']=='outTemp' and o['expected_old_value'] is None and o['new_value']==o['source_value'] for o in ops)\nassert all('RESTORED' in o['reason'] and 'MODERATE provenance' in o['reason'] and 'uncertainty' in o['reason'].lower() for o in ops)\nassert all(r['usUnits']==16 and r['interval']==5 and r['outTemp'] is not None and r['dateTime']%300==0 and r['reconstruction_row_exists']==0 and r['change_event_count']==0 for r in src)\nassert all(m['classification']=='RESTORED' and m['confidence']=='MODERATE' and m['source_evidence']['target_change_events_all_variables']==0 for m in meta)\nassert all(m['source_evidence']['archive_row_presence_by_database']=={'loucka_reconstruction':False,'pocasi-loucka.eu':False,'pocasi-loucka.eu_GW1000':False,'pocasi-loucka.eu_old':True,'old_weewx':False,'weewx_WH1080':False} for m in meta)\nassert state['eu_old_rows']==state['eu_old_unique_timestamps']==state['eu_old_outTemp_nonnull']==state['expected_unit_interval_rows']==190\nassert all(state[k]==0 for k in ('reconstruction_rows','eu_rows','gw1000_rows','old_weewx_rows','wh1080_rows','target_timestamps_with_any_change_event','target_timestamps_with_outTemp_event'))\nassert len(refs)==190 and len({int(x['observed_at_utc']) for x in refs})==190\nb={x['segment']:x for x in base};s=b['SOURCE_GAP_2023_MAY']\nassert s['rows_total']==s['station_temp_nonnull']==s['exact_reference_pairs']==190\nassert math.isclose(float(s['station_minus_reference_bias_c']),0.99343567251462,abs_tol=1e-9)\nassert math.isclose(float(s['station_reference_mae_c']),1.0124122807017544,abs_tol=1e-9)\nassert [x['size'] for x in batches['batches']]==[50,50,50,40] and sum(x['size'] for x in batches['batches'])==190\nfor f in manifest['files']:\n q=p/f['path'];raw=q.read_bytes();assert len(raw)==f['bytes'] and hashlib.sha256(raw).hexdigest()==f['sha256'],f['path']\nprint('PASS: 190 RESTORED/MODERATE source-only outTemp inserts; six-archive target absence and history; 190 exact LuhaMet pairs; 30-day baseline; 4 batches <=50; manifest; no writes.')\n''')
# Summary for follow-up and a compact per-target CSV.
(PKG/'candidate_summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
with (PKG/'per_target_archive_presence.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['timestamp','utc',*presence.keys(),'source_outTemp','LuhaMet_temp_C','source_minus_LuhaMet_C']);w.writeheader()
 for m in metas:
  ev=m['source_evidence'];w.writerow({'timestamp':m['timestamp'],'utc':m['utc'],**{k:int(v) for k,v in presence.items()},'source_outTemp':ev['source_values']['outTemp'],'LuhaMet_temp_C':ev['exact_luhamet']['temperature_c'],'source_minus_LuhaMet_C':ev['exact_luhamet']['source_minus_reference_C']})
# Build manifest last, excluding manifest itself.
manifest=[]
for pth in sorted(PKG.iterdir()):
 if pth.is_file() and pth.name!='manifest.json':
  raw=pth.read_bytes();manifest.append({'path':pth.name,'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()})
(PKG/'manifest.json').write_text(json.dumps({'schema':'meteo-proposal-package-manifest-v1','package_id':'restored-source-only-2023-may-outtemp-v1','operation_count':190,'database_writes':0,'files':manifest},ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'package':str(PKG),'operations':len(ops),'batch_sizes':[b['size'] for b in batches],'summary':summary},ensure_ascii=False,indent=2))
